<?php
/* Musicband AUDIT: consultation et statistiques réservées aux administrateurs. */
/* Route de consultation administrateur du journal, de ses filtres et statistiques.
 * Dépend de account_mail.php, business.php et des helpers audit_trail.php chargés par auth.php.
 * Interroge MySQL et gère les filtres nommés ; ne rejoue aucune action journalisée.
 */
require_once __DIR__.'/account_mail.php';
require_once __DIR__.'/business.php';
$user=MusicbandRequireLogin();if(!MusicbandCan('audit.read',$user))MusicbandFail('Accès au journal d’audit non autorisé.',403);
try{
    $db=MusicbandRbacDb();
    if(!MusicbandAuditReady($db)){MusicbandScreen('Audit trail','<p>Préparer le schéma Audit 015 dans <a href="'.MusicbandEscape(MusicbandBase().'upgrade.php').'">Upgrade</a>. Aucune collecte antérieure ne peut être reconstituée.</p>');exit;}
    $zone=MusicbandDateZone();$utc=new DateTimeZone('UTC');$today=new DateTimeImmutable('today',$zone);
    $state=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$_GET;$message='';$error=false;
    $from=$state['from']??$today->modify('-29 days')->format('Y-m-d');$to=$state['to']??$today->format('Y-m-d');
    $dates=[];foreach(['from'=>$from,'to'=>$to] as $key=>$text){
        if(!is_string($text))throw new RuntimeException('Période invalide.');$date=DateTimeImmutable::createFromFormat('!Y-m-d',$text,$zone);$errors=DateTimeImmutable::getLastErrors();
        if(!$date||($errors&&($errors['warning_count']||$errors['error_count']))||$date->format('Y-m-d')!==$text)throw new RuntimeException('Période invalide.');$dates[$key]=$date;
    }
    if($dates['from']>$dates['to']||$dates['to']>$today||$dates['from']<$today->modify('-186 days'))throw new RuntimeException('Choisir une période passée ou actuelle de six mois maximum.');
    $start=$dates['from']->setTimezone($utc)->format('Y-m-d H:i:s');$end=$dates['to']->modify('+1 day')->setTimezone($utc)->format('Y-m-d H:i:s');
    $fields=MusicbandAuditFields();$columns=$state['columns']??['occurred_at','actor','module','action','outcome','details','source_ip','location'];
    if(!is_array($columns)||count($columns)>count($fields)||array_filter($columns,fn($key)=>!is_string($key)||!isset($fields[$key])))throw new RuntimeException('Colonnes invalides.');
    $columns=array_values(array_unique($columns));if(!$columns)$columns=['occurred_at'];
    $search=$state['q']??'';if(!is_string($search)||strlen($search)>300||!preg_match('//u',$search))throw new RuntimeException('Recherche invalide.');
    $saved=MusicbandAuditPresets($db);$active=$state['preset']??'';
    if(!is_string($active)||($active!==''&&!isset($saved['items'][$active])))throw new RuntimeException('Filtre supprimé ou inconnu.');
    $rules=MusicbandAuditDecodeRules($state['rules']??($active!==''?json_encode($saved['items'][$active]['rules'],JSON_THROW_ON_ERROR):''));
    $raw=$rules['rules']?json_encode($rules,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE):'';
    if($active!==''&&$rules!==$saved['items'][$active]['rules'])$active='';
    $base=MusicbandBase().'audit.php';$query=['from'=>$from,'to'=>$to,'q'=>$search,'columns'=>$columns,'rules'=>$raw,'preset'=>$active];
    if($_SERVER['REQUEST_METHOD']==='POST'){
        try{$query['preset']=MusicbandAuditPresetSave($db);$query['notice']=($_POST['action']??'')==='filter_save'?'saved':'deleted';header('Location: '.$base.'?'.http_build_query($query),true,303);exit;}
        catch(Throwable $e){$message=$e instanceof RuntimeException&&!($e instanceof PDOException)?$e->getMessage():'Filtre non enregistré.';$error=true;MusicbandAuditEvent('audit','filter.change','rejected');}
    }
    if(($state['notice']??'')==='saved')$message='Filtre enregistré.';
    if(($state['notice']??'')==='deleted')$message='Filtre supprimé ; critères courants conservés.';
    $period='occurred_at>=? AND occurred_at<? AND occurred_at>=UTC_TIMESTAMP(6)-INTERVAL 6 MONTH';$bounds=[$start,$end];
    // Dernière connexion conservée et nombre sur la période, indépendamment des filtres du journal.
    $q=$db->prepare("SELECT actor,MAX(occurred_at) AS last_login,SUM(CASE WHEN occurred_at>=? AND occurred_at<? THEN 1 ELSE 0 END) AS logins FROM Musicbandai_audit_events WHERE action='login.success' AND occurred_at>=UTC_TIMESTAMP(6)-INTERVAL 6 MONTH GROUP BY actor ORDER BY actor");$q->execute($bounds);$stats=[];
    foreach(array_keys(MusicbandRead('users')) as $login)$stats[$login]=['last_login'=>null,'logins'=>0];
    foreach($q as $stat)if($stat['actor']!==null)$stats[$stat['actor']]=$stat;ksort($stats,SORT_NATURAL|SORT_FLAG_CASE);
    $content='<p>Journal administrateur · fuseau '.MusicbandEscape($zone->getName()).'. Conservation : six mois calendaires. Les accès observés ne prouvent pas une écriture ; les actions confirmées sont tracées séparément.</p>';
    if($message!=='')$content.='<p role="'.($error?'alert':'status').'">'.MusicbandEscape($message).'</p>';
    $periodHidden='';foreach(['q'=>$search,'rules'=>$raw,'preset'=>$active] as $key=>$value)$periodHidden.='<input type="hidden" name="'.$key.'" value="'.MusicbandEscape($value).'">';foreach($columns as $key)$periodHidden.='<input type="hidden" name="columns[]" value="'.$key.'">';
    $content.='<form method="get">'.$periodHidden.'<label>Du<input type="date" name="from" value="'.MusicbandEscape($from).'" required></label><label>Au (inclus)<input type="date" name="to" value="'.MusicbandEscape($to).'" max="'.$today->format('Y-m-d').'" required></label><button>Afficher la période</button></form>';
    $content.='<details open><summary>Connexions par utilisateur · période sélectionnée</summary><div class="Musicband-related-scroll"><table><thead><tr><th>Utilisateur</th><th>Dernière connexion conservée (six mois)</th><th>Connexions sur la période</th></tr></thead><tbody>';
    foreach($stats as $login=>$stat)$content.='<tr><td>'.MusicbandEscape((string)$login).'</td><td>'.($stat['last_login']?MusicbandEscape((new DateTimeImmutable($stat['last_login'],$utc))->setTimezone($zone)->format('d/m/Y H:i:s')):'—').'</td><td>'.(int)$stat['logins'].'</td></tr>';
    $content.='</tbody></table></div><p>Comptes actuels et comptes historiques présents dans le journal ; aucune connexion antérieure à l’installation n’est inventée.</p></details>';
    $purge=$db->query('SELECT last_purge_at,last_purge_count FROM Musicbandai_audit_settings WHERE id=1')->fetch();
    $content.='<p>Dernière purge achevée : '.($purge['last_purge_at']?MusicbandEscape((new DateTimeImmutable($purge['last_purge_at'],$utc))->setTimezone($zone)->format('d/m/Y H:i:s')).' · '.(int)$purge['last_purge_count'].' ligne(s) supprimée(s)':'aucune depuis l’installation').'. La localisation ne fait appel à aucun service externe.</p>';
    $args=$bounds;$where=$period.' AND '.MusicbandAuditSql($rules,$args);
    if($search!==''){
        $parts=[];foreach($columns as $key){if($key==='occurred_at')continue;$parts[]='`'.$key.'` LIKE ? ESCAPE \'=\'';$args[]='%'.str_replace(['=','%','_'],['==','=%','=_'],$search).'%';}
        // Rechercher une date/heure affichée se fait dans le fuseau local, sans dépendre des tables TZ MySQL.
        if(in_array('occurred_at',$columns,true))foreach(['!d/m/Y H:i:s'=>'second','!d/m/Y'=>'day','!Y-m-d'=>'day'] as $format=>$step){$d=DateTimeImmutable::createFromFormat($format,$search,$zone);$errors=DateTimeImmutable::getLastErrors();if($d&&(!$errors||(!$errors['error_count']&&!$errors['warning_count']))&&$d->format(substr($format,1))===$search){$parts[]='(occurred_at>=? AND occurred_at<?)';$args[]=$d->setTimezone($utc)->format('Y-m-d H:i:s');$args[]=$d->modify('+1 '.$step)->setTimezone($utc)->format('Y-m-d H:i:s');break;}}
        $where.=' AND ('.($parts?implode(' OR ',$parts):'0=1').')';
    }
    $q=$db->prepare('SELECT COUNT(*) FROM Musicbandai_audit_events WHERE '.$where);$q->execute($args);$count=(int)$q->fetchColumn();$pages=max(1,(int)ceil($count/50));$page=min(businessListPage('page'),$pages);
    $q=$db->prepare('SELECT * FROM Musicbandai_audit_events WHERE '.$where.' ORDER BY occurred_at DESC,id DESC LIMIT 50 OFFSET '.(($page-1)*50));$q->execute($args);$rows=$q->fetchAll();
    $config=[];foreach($fields as $key=>[$label,$kind]){
        $choices=[];
        if(in_array($key,['actor','module','action','outcome','source_ip','location','method','route'],true)){$d=$db->prepare('SELECT DISTINCT `'.$key.'` AS value FROM Musicbandai_audit_events WHERE '.$period.' AND `'.$key.'` IS NOT NULL ORDER BY `'.$key.'` LIMIT 200');$d->execute($bounds);foreach($d as $value)$choices[]=['value'=>(string)$value['value'],'label'=>(string)$value['value']];}
        $config[]=['id'=>$key,'label'=>$label,'kind'=>$kind,'operators'=>MusicbandAuditOperators($key),'choices'=>$choices];
    }
    $hidden='';foreach(['from'=>$from,'to'=>$to,'rules'=>$raw,'preset'=>$active] as $key=>$value)$hidden.='<input type="hidden" name="'.$key.'" value="'.MusicbandEscape($value).'">';
    $columnHidden='';foreach($columns as $key)$columnHidden.='<input type="hidden" name="columns[]" value="'.$key.'">';
    $hasCriteria = ($search !== '' || $active !== '' || $raw !== '');
    $summaryParts = [];
    if ($search !== '') {
        $summaryParts[] = 'Recherche : « ' . MusicbandEscape($search) . ' »';
    }
    if ($active !== '' && isset($saved['items'][$active])) {
        $summaryParts[] = 'Filtre : « ' . MusicbandEscape($saved['items'][$active]['name']) . ' »';
    } elseif ($raw !== '') {
        $summaryParts[] = 'Critères personnalisés';
    }
    $summaryParts[] = $count . ' événement' . ($count > 1 ? 's' : '');
    $activeCriteriaCount = ($search !== '' ? 1 : 0) + ($active !== '' ? 1 : 0) + ($raw !== '' ? 1 : 0);
    $summaryText = $hasCriteria ? 'Filtres actifs (' . $activeCriteriaCount . ') : ' . implode(' · ', $summaryParts) : 'Aucun filtre actif · ' . $count . ' événement' . ($count > 1 ? 's' : '');
    $resetUrl = $base . '?' . http_build_query(['from' => $from, 'to' => $to, 'columns' => $columns]);
    $quickReset = $hasCriteria ? '<a class="Musicband-search-quick-reset" href="' . MusicbandEscape($resetUrl) . '" title="Effacer la recherche et les critères">Effacer</a>' : '';
    $chevronSvg = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>';

    // Section de recherche et critères repliable par défaut
    $content .= '<details class="Musicband-search-collapsible" id="audit-search-panel">';
    $content .= '<summary class="Musicband-search-header"><div class="Musicband-search-header-main">';
    $content .= '<span class="Musicband-search-chevron">' . $chevronSvg . '</span>';
    $content .= '<span class="Musicband-search-title">Recherche et critères</span>';
    $content .= '<span class="Musicband-search-summary-badge' . ($hasCriteria ? ' is-active' : '') . '" role="status">' . $summaryText . '</span>';
    $content .= '</div>' . $quickReset . '</summary>';
    $content .= '<div class="Musicband-search-body">';
    $content .= '<form method="get" id="audit-search">' . $hidden . $columnHidden . '<div class="songs-search-bar"><label>Rechercher<input name="q" value="' . MusicbandEscape($search) . '" placeholder="Dans les colonnes affichées"></label><button class="button-primary">Rechercher</button><button type="button" class="button-secondary" id="audit-advanced-toggle" aria-expanded="false" aria-controls="audit-advanced" hidden>+ Recherche avancée</button>';
    foreach ($saved['items'] as $key => $preset) $content .= '<a class="song-filter-preset' . ($active === $key ? ' is-active' : '') . '" href="' . MusicbandEscape($base . '?' . http_build_query(['from' => $from, 'to' => $to, 'columns' => $columns, 'preset' => $key])) . '"' . ($active === $key ? ' aria-current="true"' : '') . '>' . MusicbandEscape($preset['name']) . '</a>';
    $content .= '</div><section id="audit-advanced" hidden><p>ET / OU / NON ; valeurs existantes proposées (200 maximum par attribut), ou saisie libre. Les horodatages utilisent le fuseau affiché.</p><div id="audit-builder"></div><p id="audit-filter-error" role="alert" hidden></p><button class="button-primary">Appliquer les critères</button>' . ($raw !== '' ? '<button type="button" class="button-secondary" id="audit-filter-save">Enregistrer le filtre</button>' : '') . '<button type="button" class="button-secondary" id="audit-filter-clear">Effacer les critères</button>' . ($active !== '' ? '<button type="button" class="button-danger" id="audit-filter-delete" data-filter-name="' . MusicbandEscape($saved['items'][$active]['name']) . '">Supprimer ce filtre</button>' : '') . '</section><p><a href="' . MusicbandEscape($resetUrl) . '">Effacer recherche et critères</a></p><noscript>Le constructeur avancé nécessite JavaScript ; la recherche, les filtres nommés et la pagination restent accessibles.</noscript></form>';
    $content .= '</div></details>';
    $content.='<form method="post" id="audit-filter-store" hidden>'.$hidden.$columnHidden.'<input type="hidden" name="q" value="'.MusicbandEscape($search).'"><input type="hidden" name="csrf" value="'.MusicbandEscape($_SESSION['csrf']).'"><input type="hidden" name="action"><input type="hidden" name="filter_name"><input type="hidden" name="confirm_filter"><input type="hidden" name="filter_version" value="'.$saved['version'].'"></form>';
    $content.='<details><summary>Colonnes affichées</summary><form method="get">'.$hidden.'<input type="hidden" name="q" value="'.MusicbandEscape($search).'">';foreach($fields as $key=>[$label])$content.='<label><input type="checkbox" name="columns[]" value="'.$key.'"'.(in_array($key,$columns,true)?' checked':'').'>'.MusicbandEscape($label).'</label>';$content.='<button class="button-secondary">Afficher ces colonnes</button></form></details>';
    $content.='<section><h2>Journal · '.$count.' événements</h2><div class="business-table-scroll"><table><thead><tr>';foreach($columns as $key)$content.='<th>'.MusicbandEscape($fields[$key][0]).'</th>';$content.='</tr></thead><tbody>';
    foreach($rows as $row){$content.='<tr>';foreach($columns as $key){$value=$row[$key]??'—';if($key==='occurred_at')$value=(new DateTimeImmutable($value,$utc))->setTimezone($zone)->format('d/m/Y H:i:s');$content.='<td><span class="Musicband-table-label">'.MusicbandEscape($fields[$key][0]).'</span><span class="Musicband-cell-value">'.MusicbandEscape((string)$value).'</span></td>';}$content.='</tr>';}
    $content.='</tbody></table></div><nav>Page '.$page.' / '.$pages;foreach(['Précédente'=>$page-1,'Suivante'=>$page+1] as $label=>$n)if($n>=1&&$n<=$pages)$content.=' <a href="'.MusicbandEscape($base.'?'.http_build_query($query+['page'=>$n])).'">'.$label.'</a>';$content.='</nav></section>';
    $script=base64_decode('')."\n;\nwindow.MusicbandAdvancedFilters=".json_encode(['prefix'=>'audit','filters'=>$config,'rules'=>$rules],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).";\n".base64_decode('');
    MusicbandScreen('Audit trail',$content,$script);
}catch(Throwable $e){MusicbandScreen('Audit trail','<p role="alert">'.MusicbandEscape($e instanceof RuntimeException&&!($e instanceof PDOException)?$e->getMessage():'Audit indisponible : vérifier le schéma 015 et la base.').'</p><p><a href="'.MusicbandEscape(MusicbandBase().'audit.php').'">Réinitialiser la période et les critères</a></p>');}
